using FluentValidation;using Microsoft.EntityFrameworkCore;using SchoolERP.Application.Abstractions;using SchoolERP.Application.Common.Extensions;using SchoolERP.Application.Common.Pagination;using SchoolERP.Application.Exceptions;using SchoolERP.Application.Features.Schools;using SchoolERP.Application.Security;using SchoolERP.Domain.Entities;using SchoolERP.Domain.Enums;
namespace SchoolERP.Application.Features.Departments;
public sealed class DepartmentService(IApplicationDbContext db,ICurrentSchoolResolver current,IResourceScopeValidator scope,IValidator<CreateDepartmentRequest> cv,IValidator<UpdateDepartmentRequest> uv,IValidator<ChangeDepartmentCodeRequest> ccv,TimeProvider clock):IDepartmentService{
 public async Task<PagedResult<DepartmentListItemDto>> ListAsync(GetDepartmentsQuery r,CancellationToken ct=default){var sid=await current.ResolveAsync(ct);if(r.CampusId.HasValue)await Campus(r.CampusId.Value,sid,false,ct);var q=Visible(db.Departments.AsNoTracking().Where(x=>x.SchoolId==sid)).WhereIf(r.CampusId.HasValue,x=>x.CampusId==r.CampusId).WhereIf(r.SchoolWideOnly,x=>x.CampusId==null).WhereIf(r.Type.HasValue,x=>x.Type==r.Type).WhereIf(r.Status.HasValue,x=>x.Status==r.Status);if(!string.IsNullOrWhiteSpace(r.Search)){var t=r.Search.Trim().ToLower();q=q.Where(x=>x.Name.ToLower().Contains(t)||x.Code.ToLower().Contains(t)||(x.ShortName!=null&&x.ShortName.ToLower().Contains(t))||(x.HeadName!=null&&x.HeadName.ToLower().Contains(t))||(x.Email!=null&&x.Email.ToLower().Contains(t))||(x.Location!=null&&x.Location.ToLower().Contains(t)));}var d=string.Equals(r.SortDirection,"desc",StringComparison.OrdinalIgnoreCase);q=(r.SortBy?.ToLowerInvariant(),d) switch{("name",false)=>q.OrderBy(x=>x.Name),("name",true)=>q.OrderByDescending(x=>x.Name),("code",false)=>q.OrderBy(x=>x.Code),("code",true)=>q.OrderByDescending(x=>x.Code),("type",false)=>q.OrderBy(x=>x.Type),("type",true)=>q.OrderByDescending(x=>x.Type),("status",false)=>q.OrderBy(x=>x.Status),("status",true)=>q.OrderByDescending(x=>x.Status),("createdat",false)=>q.OrderBy(x=>x.CreatedAt),("createdat",true)=>q.OrderByDescending(x=>x.CreatedAt),("campus",false)=>q.OrderBy(x=>x.Campus!.Name),("campus",true)=>q.OrderByDescending(x=>x.Campus!.Name),_=>q.OrderBy(x=>x.DisplayOrder).ThenBy(x=>x.Name)};return await q.Select(x=>new DepartmentListItemDto(x.Id,x.Name,x.Code,x.ShortName,x.Type,x.DisplayOrder,x.CampusId,x.Campus!=null?x.Campus.Name:null,x.HeadName,x.Email,x.Phone,x.Status,x.CreatedAt,x.UpdatedAt)).ToPagedResultAsync(new(r.PageNumber,r.PageSize),ct);}
 public async Task<DepartmentDetailsDto?> GetAsync(Guid id,CancellationToken ct=default){var sid=await current.ResolveAsync(ct);return await Visible(db.Departments.AsNoTracking().Where(x=>x.Id==id&&x.SchoolId==sid)).Select(x=>new DepartmentDetailsDto(x.Id,x.Name,x.Code,x.ShortName,x.Type,x.DisplayOrder,x.CampusId,x.Campus!=null?x.Campus.Name:null,x.HeadName,x.Email,x.Phone,x.Location,x.Description,x.Status,x.ActivatedAt,x.DeactivatedAt,x.ArchivedAt,x.CreatedAt,x.UpdatedAt)).SingleOrDefaultAsync(ct);}
 public async Task<DepartmentDetailsDto> CreateAsync(CreateDepartmentRequest r,CancellationToken ct=default){await cv.ValidateAndThrowAsync(r,ct);var sid=await current.ResolveAsync(ct);var school=await School(sid,ct);if(r.CampusId.HasValue)await Campus(r.CampusId.Value,sid,true,ct);await Unique(sid,r.Code,r.Name,null,ct);var x=Department.Create(school.TenantId,sid,r.CampusId,r.Name,r.Code,r.Type,r.DisplayOrder,r.HeadName,r.Email,r.Phone,r.Location,r.Description,r.ShortName,Now());db.Departments.Add(x);await db.SaveChangesAsync(ct);return(await GetAsync(x.Id,ct))!;}
 public async Task<DepartmentDetailsDto?> UpdateAsync(Guid id,UpdateDepartmentRequest r,CancellationToken ct=default){await uv.ValidateAndThrowAsync(r,ct);var x=await Write(id,ct);if(x is null)return null;await School(x.SchoolId,ct);await Unique(x.SchoolId,x.Code,r.Name,id,ct);x.UpdateDetails(r.Name,r.ShortName,r.Type,r.DisplayOrder,r.HeadName,r.Email,r.Phone,r.Location,r.Description,Now());await db.SaveChangesAsync(ct);return await GetAsync(id,ct);}
 public async Task<DepartmentDetailsDto?> ChangeCodeAsync(Guid id,ChangeDepartmentCodeRequest r,CancellationToken ct=default){await ccv.ValidateAndThrowAsync(r,ct);var x=await Write(id,ct);if(x is null)return null;await School(x.SchoolId,ct);await Unique(x.SchoolId,r.Code,x.Name,id,ct);x.ChangeCode(r.Code,Now());await db.SaveChangesAsync(ct);return await GetAsync(id,ct);}
 public Task<DepartmentDetailsDto?> ActivateAsync(Guid id,CancellationToken ct=default)=>Change(id,async x=>{var school=await db.Schools.AsNoTracking().SingleAsync(s=>s.Id==x.SchoolId,ct);if(school.Status!=SchoolStatus.Active)throw new ParentNotOperationalException("Department.SchoolUnavailable");if(x.CampusId.HasValue){var campus=await Campus(x.CampusId.Value,x.SchoolId,false,ct);if(campus.Status!=CampusStatus.Active)throw new DepartmentCampusUnavailableException();}x.Activate(Now());},ct); public Task<DepartmentDetailsDto?> DeactivateAsync(Guid id,CancellationToken ct=default)=>Change(id,x=>{x.Deactivate(Now());return Task.CompletedTask;},ct); public Task<DepartmentDetailsDto?> ArchiveAsync(Guid id,CancellationToken ct=default)=>Change(id,x=>{x.Archive(Now());return Task.CompletedTask;},ct);
 private async Task<DepartmentDetailsDto?> Change(Guid id,Func<Department,Task> action,CancellationToken ct){var x=await Write(id,ct);if(x is null)return null;await action(x);await db.SaveChangesAsync(ct);return await GetAsync(id,ct);} private IQueryable<Department> Visible(IQueryable<Department> q)=>scope.CampusId.HasValue?q.Where(x=>x.CampusId==null||x.CampusId==scope.CampusId):q; private async Task<Department?> Write(Guid id,CancellationToken ct){var sid=await current.ResolveAsync(ct);return await Visible(db.Departments.Where(x=>x.Id==id&&x.SchoolId==sid)).SingleOrDefaultAsync(ct);} private async Task<School> School(Guid id,CancellationToken ct){var x=await db.Schools.AsNoTracking().SingleAsync(s=>s.Id==id,ct);if(x.Status is SchoolStatus.Suspended or SchoolStatus.Archived)throw new ParentNotOperationalException("Department.SchoolUnavailable");return x;} private async Task<Campus> Campus(Guid id,Guid sid,bool forCreate,CancellationToken ct){if(!scope.CanAccessCampus(sid,id))throw new ResourceNotFoundException("Campus");var x=await db.Campuses.AsNoTracking().SingleOrDefaultAsync(c=>c.Id==id&&c.SchoolId==sid,ct)??throw new ResourceNotFoundException("Campus");if(forCreate&&x.Status is CampusStatus.Suspended or CampusStatus.Archived)throw new DepartmentCampusUnavailableException();return x;} private async Task Unique(Guid sid,string code,string name,Guid? except,CancellationToken ct){var c=Department.NormalizeCode(code);var n=name.Trim().ToLower();if(await db.Departments.AsNoTracking().AnyAsync(x=>x.SchoolId==sid&&x.Code==c&&(!except.HasValue||x.Id!=except),ct))throw new DepartmentCodeConflictException();if(await db.Departments.AsNoTracking().AnyAsync(x=>x.SchoolId==sid&&x.Name.ToLower()==n&&(!except.HasValue||x.Id!=except),ct))throw new DepartmentNameConflictException();} private DateTime Now()=>clock.GetUtcNow().UtcDateTime;
}
